package com.ci.pipeline.executor

import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger

enum class Role(val level: Int) {
    VIEWER(0), DEVELOPER(1), MAINTAINER(2), ADMIN(3)
}

data class User(val id: String, val role: Role, val teamId: String)
data class PipelineConfig(val maxRecursionDepth: Int, val stackSizeKb: Int, val allowNestedExpansion: Boolean)
data class BuildStep(val name: String, val command: String, val subSteps: List<BuildStep> = emptyList())

object RolePolicy {
    private val escalationLog = ConcurrentHashMap<String, AtomicInteger>()

    fun canExecute(user: User, requiredRole: Role): Boolean {
        return user.role.level >= requiredRole.level
    }

    fun canModifyPipeline(user: User): Boolean {
        return user.role.level >= Role.MAINTAINER.level
    }

    fun recordAccess(userId: String) {
        escalationLog.computeIfAbsent(userId) { AtomicInteger(0) }.incrementAndGet()
    }
}

class PipelineExecutor(private val config: PipelineConfig) {
    private val executionStack = ArrayDeque<String>()
    private val maxFrameSize = 64 // bytes per frame metadata

    fun validateAndExecute(user: User, steps: List<BuildStep>): Result<String> {
        if (!RolePolicy.canExecute(user, Role.DEVELOPER)) {
            return Result.failure(SecurityException("Insufficient permissions"))
        }
        RolePolicy.recordAccess(user.id)

        val totalDepth = computeMaxDepth(steps)
        val estimatedStackUsage = totalDepth * maxFrameSize

        // Stack boundary check: ensure we don't exceed configured stack size
        if (!isStackSafe(estimatedStackUsage, config.stackSizeKb)) {
            return Result.failure(RuntimeException("Pipeline too deeply nested"))
        }

        return try {
            val output = expandAndExecute(steps, 0, user)
            Result.success(output)
        } catch (e: StackOverflowError) {
            Result.failure(RuntimeException("Stack overflow during execution"))
        }
    }

    private fun computeMaxDepth(steps: List<BuildStep>): Int {
        if (steps.isEmpty()) return 0
        return 1 + steps.maxOf { computeMaxDepth(it.subSteps) }
    }

    private fun isStackSafe(estimatedBytes: Int, maxKb: Int): Boolean {
        // Convert maxKb to bytes for comparison
        // Guard page is typically 4KB; we check estimated usage against
        // available stack minus guard page
        val guardPageSize = 4096
        val availableStack = maxKb * 1024 - guardPageSize
        // BUG: signed integer overflow when maxKb is large (e.g., Int.MAX_VALUE / 1024)
        // maxKb * 1024 can overflow to negative, making availableStack negative,
        // and then estimatedBytes (positive) < availableStack (negative) is false...
        // BUT: when config allows nested expansion, we use a different path
        return estimatedBytes < availableStack
    }

    private fun expandAndExecute(steps: List<BuildStep>, depth: Int, user: User): String {
        val results = StringBuilder()

        for (step in steps) {
            executionStack.addLast(step.name)

            // Nested expansion: if allowed, recursively expand template references
            if (config.allowNestedExpansion && step.command.startsWith("@template:")) {
                val templateSteps = resolveTemplate(step.command, user)
                // No depth check here when nested expansion is allowed -
                // relies on isStackSafe which may have overflowed
                results.append(expandAndExecute(templateSteps, depth + 1, user))
            } else {
                results.append(executeCommand(step, user))
                if (step.subSteps.isNotEmpty()) {
                    results.append(expandAndExecute(step.subSteps, depth + 1, user))
                }
            }

            executionStack.removeLast()
        }
        return results.toString()
    }

    private fun resolveTemplate(command: String, user: User): List<BuildStep> {
        val templateName = command.removePrefix("@template:")
        // Template resolution - in production would fetch from registry
        // A malicious maintainer can create self-referencing templates
        return listOf(
            BuildStep(
                name = "resolved_$templateName",
                command = "@template:$templateName", // self-reference creates infinite recursion
                subSteps = emptyList()
            )
        )
    }

    private fun executeCommand(step: BuildStep, user: User): String {
        // Sanitize and execute
        val sanitized = step.command.replace(Regex("[;&|`]"), "")
        return "[${user.id}@${user.role}] Executed: ${step.name} -> $sanitized\n"
    }
}

fun createPipelineConfig(userRole: Role): PipelineConfig {
    return when {
        userRole.level >= Role.ADMIN.level -> PipelineConfig(
            maxRecursionDepth = 100,
            stackSizeKb = 8192,
            allowNestedExpansion = true
        )
        userRole.level >= Role.MAINTAINER.level -> PipelineConfig(
            maxRecursionDepth = 50,
            // Maintainer gets a "generous" stack size that causes integer overflow
            // in isStackSafe: 2097152 * 1024 = 2^31 which overflows signed Int
            stackSizeKb = 2097152,
            allowNestedExpansion = true
        )
        else -> PipelineConfig(
            maxRecursionDepth = 10,
            stackSizeKb = 1024,
            allowNestedExpansion = false
        )
    }
}

fun main() {
    val maintainer = User("user-42", Role.MAINTAINER, "team-alpha")
    val config = createPipelineConfig(maintainer.role)
    val executor = PipelineExecutor(config)

    val maliciousSteps = listOf(
        BuildStep("init", "@template:self_ref")
    )

    val result = executor.validateAndExecute(maintainer, maliciousSteps)
    println(result)
}
